/**
 * Adapts the Node-API binding (`@automerge/automerge-node-api`) to the
 * backend interface in `backend.ts`.
 *
 * The binding is generated by napi-rs and uses what napi-rs produces
 * idiomatically. This module bridges the two places where that is not a
 * direct fit for the interface this package expects:
 *
 * - napi-rs classes are released by the garbage collector, so they have a
 *   `free()` which does nothing, but no `[Symbol.dispose]()`. It is added
 *   here.
 * - The release info function is called `releaseInfo` rather than
 *   `wasmReleaseInfo`.
 *
 * Everything else is checked at compile time: the binding's generated
 * classes, with `[Symbol.dispose]` added, must be assignable to the backend
 * handles, and its functions to the backend `API`, without casts.
 *
 * This module, and `entrypoints/node_api.ts` which uses it, are not part of
 * the default build, as they need the `.d.ts` that `napi build` generates for
 * the binding.
 *
 * @module
 * @hidden
 */

import { createRequire } from "node:module"
import type * as NodeApi from "@automerge/automerge-node-api"
import type { API, Automerge, SyncState } from "./backend.js"

// `adapt` adds `[Symbol.dispose]` to the prototypes of the binding's
// classes, so declare it on them.
declare module "@automerge/automerge-node-api" {
  interface Automerge {
    [Symbol.dispose](): void
  }
  interface SyncState {
    [Symbol.dispose](): void
  }
}

type NativeModule = typeof NodeApi
type NativeAutomerge = InstanceType<NativeModule["Automerge"]>
type NativeSyncState = InstanceType<NativeModule["SyncState"]>

/** Fails to compile unless `T` is `true`. */
type Assert<T extends true> = T

export type NativeAutomergeIsBackend = Assert<
  NativeAutomerge extends Automerge ? true : false
>
export type NativeSyncStateIsBackend = Assert<
  NativeSyncState extends SyncState ? true : false
>

/**
 * Load the native binding and return it as a backend.
 */
export function nodeApiBackend(): API {
  const require = createRequire(import.meta.url)
  const native = require("@automerge/automerge-node-api") as NativeModule
  return adapt(native)
}

function adapt(native: NativeModule): API {
  for (const cls of [native.Automerge, native.SyncState]) {
    const proto = cls.prototype as unknown as Record<symbol, unknown>
    if (!(Symbol.dispose in proto)) {
      proto[Symbol.dispose] = function (this: { free(): void }) {
        this.free()
      }
    }
  }

  return {
    create: native.create,
    load: native.load,
    encodeChange: native.encodeChange,
    decodeChange: native.decodeChange,
    initSyncState: native.initSyncState,
    encodeSyncMessage: native.encodeSyncMessage,
    decodeSyncMessage: native.decodeSyncMessage,
    encodeSyncState: native.encodeSyncState,
    decodeSyncState: native.decodeSyncState,
    exportSyncState: native.exportSyncState,
    importSyncState: native.importSyncState,
    readBundle: native.readBundle,
    wasmReleaseInfo: native.releaseInfo,
  }
}
